message.content:
{
  "pitches": [
    {
      "key": "academy_vending_choice",
      "title": "자판기와 동전의 행방",
      "premise": "토우마의 동전을 삼킨 자판기가 덜컥거리며 멈춰 섰고, 미코토는 익숙한 듯 주먹을 쥐며 비법을 읊으려 한다. 여행자는 멈춘 자판기 앞에 서서 덜컥거리는 기계의 떨림을 느낀다. 나는 지금 자판기 앞의 동전을 챙길지, 아니면 미코토의 행동을 제지할지 결정해야 한다.",
      "choices": [
        "미코토의 손을 잡아 세우고 자판기 옆의 빈 공간을 확보한다.",
        "자판기 안의 동전이 튀어나오는지 살피며 토우마의 가방을 건넨다.",
        "미코토의 비법이 실행되기 전, 주변에 다른 사람이 오는지 살핀다."
      ],
      "basis": "금서목록 1기 10화. 자판기가 돈을 삼킨 상황. 원작의 자판기 파괴나 동생 만남은 배제."
    },
    {
      "key": "academy_patisserie_tea",
      "title": "중단된 티타임의 잔",
      "premise": "파티스리에서 케이크를 나누려던 순간 풍기위원 호출이 울렸고, 쿠로코와 우이하루는 자리에서 일어선다. 사텐은 아직 채 마시지 못한 찻잔을 든 채 멈춰 섰다. 나는 내 찻잔을 내려놓을지, 아니면 사텐의 잔을 챙겨줄지 결정해야 한다.",
      "choices": [
        "내 찻잔을 테이블 구석에 밀어 넣고 사텐의 짐을 먼저 챙긴다.",
        "사텐의 찻잔을 들고 이동하며 쿠로코의 위치를 확인한다.",
        "찻잔을 그대로 둔 채 호출 장소로 향하는 길을 안내한다."
      ],
      "basis": "초전자포 1기 3화. 파티스리 방문 중 호출 상황. 사텐의 피습이나 범인 체포는 배제."
    },
    {
      "key": "academy_waiting_spot",
      "title": "답을 기다리는 대기석",
      "premise": "쿠로코가 무리하게 앞서 나가려 하자 우이하루가 멈춰 서서 아직 답하지 못한 약속에 대해 언급한다. 두 사람 사이에는 팽팽한 공기가 흐르고, 여행자는 그들 사이의 대기 공간에 서 있다. 나는 두 사람의 시선이 닿는 곳에서 어떤 행동을 취할지 결정해야 한다.",
      "choices": [
        "우이하루 옆에 서서 그녀가 건네는 질문에 고개를 끄덕인다.",
        "쿠로코의 앞을 가로막아 잠시 숨을 고를 시간을 준다.",
        "두 사람의 대화에 끼지 않고 주변의 다음 이동 경로를 살핀다."
      ],
      "basis": "초전자포 1기 5화. 쿠로코와 우이하루의 갈등 상황. 화해나 폭행 내용은 배제."
    },
    {
      "key": "academy_arcade_button",
      "title": "남겨진 버튼의 잔상",
      "premise": "코노에가 떠난 뒤 오락실 의자에는 아직 눌리지 않은 버튼이 빛나고 있고, 테츠소는 멍하니 조이스틱을 잡고 있다. 여행자는 그 옆에서 멈춰 선 테츠소의 손끝을 바라본다. 나는 이 버튼을 다시 누를지, 아니면 기계를 끄는 것을 도울지 결정해야 한다.",
      "choices": [
        "테츠소의 손 위로 손을 겹쳐 버튼을 누르는 것을 돕는다.",
        "테츠소에게 기계의 전원 버튼 위치를 가리켜 보여준다.",
        "테츠소의 시선을 돌리기 위해 옆에 있는 다른 게임기 쪽을 가리킨다."
      ],
      "basis": "초전자포 1기 17화. 게임 도중 떠난 학생과 남겨진 테츠소. 게임 승패나 사정은 배제."
    },
    {
      "key": "academy_performance_supply",
      "title": "무대 뒤의 보급품",
      "premise": "성하제 안내 중 미코토가 무대 순서를 떠올리며 긴장한 기색을 보이고, 여행자는 무대 옆 비품 상자를 살핀다. 쿠로코는 메이드 복장을 한 채 업무를 위해 멀리 이동 중이다. 나는 미코토에게 어떤 소품을 먼저 건넬지 결정해야 한다.",
      "choices": [
        "미코토의 손에 무대용 소품 상자의 뚜껑을 열어 보여준다.",
        "미코토의 긴장을 풀어주기 위해 주변의 빈 의자를 안내한다.",
        "멀어지는 쿠로코의 동선을 확인하며 미코토의 옆을 지킨다."
      ],
      "basis": "초전자포 1기 19화. 성하제 준비 상황. 공연 종류나 곡 등은 특정하지 않음."
    },
    {
      "key": "academy_pool_cleaning",
      "title": "수영장 바닥의 물때",
      "premise": "사감이 내린 수영장 청소 업무로 미코토와 쿠로코가 바닥에 엎드려 걸레질을 시작한다. 여행자는 물이 고인 구석의 물때를 발견한다. 나는 이 구석을 먼저 닦을지, 아니면 다른 구역의 걸레를 가져올지 결정해야 한다.",
      "choices": [
        "물때가 있는 곳에 걸레를 밀어 넣으며 미코토에게 신호를 보낸다.",
        "다른 구역의 물을 퍼낼 양동이를 먼저 가져온다.",
        "쿠로코의 걸레질 속도가 늦어지는 곳으로 이동해 보조한다."
      ],
      "basis": "초전자포 1기 2화. 수영장 청소 징계 상황. 능력 전투나 징계 취소는 배제."
    }
  ]
}
